/**
 * PDF, Excel (.xlsx), and CSV export builders + export-audit logger for the
 * Landlord Ops Calling Center Reports tab.
 *
 * Rules obeyed:
 *   - Never computes or re-derives figures in the browser: every total and row
 *     comes from the `landlord_cc_*` server RPC responses passed in.
 *   - Does NOT edit `callingCenterWeeklyForwardingPdf.ts`, `callingCenterAllCalls.ts`,
 *     or any Tenant Ops report file.
 *   - PDF follows the `jspdf` / `jspdf-autotable` pattern: Welile header, period,
 *     generated by/at, page numbers (`Page X of Y`), and content-height pages
 *     capped at A4 (`<= 297 mm` height).
 *   - Logs every export to `public.audit_logs` in the standard export-audit pattern.
 */
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { format } from 'date-fns';
import { supabase } from '@/integrations/supabase/client';
import { downloadXlsxWorkbook, type XlsxSheet } from '@/lib/xlsxExport';
import { downloadCsvWithPreamble } from '@/lib/csvExport';
import type {
  LandlordCallLogRow,
  LandlordConcernsReportData,
  LandlordCoverageRow,
  LandlordDailySummaryRow,
  LandlordRoundReportData,
  LandlordStaffPerformanceRow,
  LandlordWeeklyReportData,
} from '@/hooks/useLandlordCallingReports';

export const A4_WIDTH_MM = 210;
export const A4_MAX_HEIGHT_MM = 297;
export const MIN_CONTENT_PAGE_HEIGHT_MM = 95;

export interface LandlordReportExportPayload {
  from: string;
  to: string;
  weekStart: string;
  generatedBy: string;
  generatedAt?: Date;
  dailySummary: LandlordDailySummaryRow[];
  weeklyReport: LandlordWeeklyReportData | null;
  coverage: LandlordCoverageRow[];
  staffPerformance: LandlordStaffPerformanceRow[];
  callLog: LandlordCallLogRow[];
  concernsReport: LandlordConcernsReportData | null;
  roundReport: LandlordRoundReportData | null;
}

export interface BuiltLandlordReportPdf {
  doc: jsPDF;
  filename: string;
  totalPages: number;
  pageHeights: number[];
}

const SOURCE_LABELS: Record<string, string> = {
  calling_center: 'Calling Center',
  received: 'Received Call',
  awareness: 'Rent Plan Awareness',
  pipeline_landlord: 'Landlord Verification',
  crm_voice: 'In-App Voice',
  legacy_landlord: 'Historical Log',
};

export function formatCallSourceLabel(source: string): string {
  return SOURCE_LABELS[source] ?? source.replace(/_/g, ' ');
}

/**
 * Standard non-blocking export audit logger writing to `public.audit_logs`.
 */
export async function logLandlordReportExport(
  actionType: 'pdf_report_exported' | 'bulk_data_exported' | 'csv_exported',
  filename: string,
  metadata: Record<string, unknown>,
): Promise<void> {
  try {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return;
    await supabase.from('audit_logs').insert({
      user_id: user.id,
      action_type: actionType,
      table_name: 'export',
      metadata: {
        module: 'landlord_calling_center_reports',
        filename,
        ...metadata,
        exported_at: new Date().toISOString(),
      },
    });
  } catch {
    // Non-blocking audit log
  }
}

/**
 * Pure PDF document builder for the Landlord Calling Center report.
 * Sizes each page to its rendered content height while capping every page at A4 (`297 mm`).
 */
export function buildLandlordCallingReportPdfDoc(
  payload: LandlordReportExportPayload,
): BuiltLandlordReportPdf {
  const generatedAt = payload.generatedAt ?? new Date();
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const pageW = doc.internal.pageSize.getWidth(); // 210 mm
  const pageMaxY = new Map<number, number>();

  const recordY = (y: number) => {
    const p = doc.getCurrentPageInfo().pageNumber;
    const prev = pageMaxY.get(p) ?? 0;
    if (y > prev) pageMaxY.set(p, y);
  };

  // 1. Welile Header Banner
  doc.setFillColor(15, 23, 42);
  doc.rect(0, 0, pageW, 24, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(13);
  doc.text('WELILE — Landlord Ops Calling Center Report', 12, 10);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8.5);
  const periodLabel = `Period: ${payload.from} to ${payload.to} (Kampala)  ·  Week (Wed–Tue): ${
    payload.weeklyReport?.week_start ?? payload.weekStart
  } to ${payload.weeklyReport?.week_end ?? payload.to}`;
  doc.text(periodLabel, 12, 16);
  doc.text(
    `Generated by ${payload.generatedBy || 'Staff member'} on ${format(
      generatedAt,
      'dd MMM yyyy HH:mm',
    )}`,
    12,
    21,
  );

  let y = 30;
  recordY(y);

  // 2. Server-provided KPI summary strip (from weeklyReport / concernsReport / roundReport)
  const wkTotals = payload.weeklyReport?.totals;
  const roundTotals = payload.roundReport?.totals;
  const concernTotals = payload.concernsReport?.totals;

  const cards = [
    {
      label: 'Weekly Landlord Calls',
      value: String(wkTotals?.total_calls ?? 0),
      sub: `Made ${wkTotals?.made_calls ?? 0} · Received ${wkTotals?.received_calls ?? 0}`,
    },
    {
      label: 'Reached / Engaged',
      value: `${wkTotals?.reached_calls ?? 0} / ${wkTotals?.engaged_calls ?? 0}`,
      sub: `Unreachable ${wkTotals?.unreachable_calls ?? 0} · Callback ${wkTotals?.callback_calls ?? 0}`,
    },
    {
      label: 'Solved Here vs Forwarded',
      value: `${wkTotals?.solved_here_total ?? 0} / ${wkTotals?.forwarded_total ?? 0}`,
      sub: `Overdue concerns: ${concernTotals?.overdue_concerns ?? 0}`,
    },
    {
      label: 'Current Round Status',
      value: `${roundTotals?.reached_count ?? 0} / ${roundTotals?.total_rows ?? 0}`,
      sub: `Parked ${roundTotals?.parked_count ?? 0} · Outstanding ${roundTotals?.outstanding_count ?? 0}`,
    },
  ];

  const cardGap = 3;
  const cardW = (pageW - 24 - cardGap * (cards.length - 1)) / cards.length;
  cards.forEach((c, idx) => {
    const x = 12 + idx * (cardW + cardGap);
    doc.setFillColor(248, 250, 252);
    doc.setDrawColor(226, 232, 240);
    doc.roundedRect(x, y, cardW, 17, 1.5, 1.5, 'FD');
    doc.setTextColor(100, 116, 139);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(6.5);
    doc.text(c.label.toUpperCase(), x + 2.5, y + 4.5);
    doc.setTextColor(15, 23, 42);
    doc.setFontSize(10.5);
    doc.text(c.value, x + 2.5, y + 10.5);
    doc.setTextColor(71, 85, 105);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(6.5);
    doc.text(c.sub, x + 2.5, y + 15);
  });

  y += 22;
  recordY(y);

  const ensureRoom = (neededMm: number) => {
    if (y + neededMm > A4_MAX_HEIGHT_MM - 18) {
      doc.addPage();
      y = 14;
      recordY(y);
    }
  };

  const sectionHeading = (title: string) => {
    ensureRoom(16);
    doc.setTextColor(15, 23, 42);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9.5);
    doc.text(title, 12, y);
    y += 2.5;
    recordY(y);
  };

  // Section 1: Daily Summary
  sectionHeading(`1. Daily Summary (${payload.from} to ${payload.to})`);
  autoTable(doc, {
    startY: y,
    margin: { left: 12, right: 12, bottom: 16 },
    head: [['Kampala Day', 'Caller', 'Total', 'Reached', 'Engaged', 'Unreachable', 'Callbacks', 'Made', 'Received']],
    body:
      payload.dailySummary.length > 0
        ? payload.dailySummary.map((r) => [
            r.kampala_day,
            r.staff_name,
            r.total_calls,
            r.reached_calls,
            r.engaged_calls,
            r.unreachable_calls,
            r.callback_calls,
            r.made_calls,
            r.received_calls,
          ])
        : [['—', 'No landlord calls in selected date range', 0, 0, 0, 0, 0, 0, 0]],
    styles: { fontSize: 7, cellPadding: 1.6 },
    headStyles: { fillColor: [30, 41, 59], textColor: 255, fontStyle: 'bold' },
    didDrawPage: (d) => {
      if (d.cursor?.y) recordY(d.cursor.y);
    },
  });
  y = ((doc as any).lastAutoTable?.finalY ?? y) + 6;
  recordY(y);

  // Section 2: Weekly Report (Wed-Tue)
  if (payload.weeklyReport) {
    const wk = payload.weeklyReport;
    sectionHeading(`2. Weekly Report (Wed–Tue: ${wk.week_start} to ${wk.week_end})`);
    autoTable(doc, {
      startY: y,
      margin: { left: 12, right: 12, bottom: 16 },
      head: [['Day', 'Total Calls', 'Made', 'Received', 'Reached', 'Engaged', 'Callbacks', 'Solved Here', 'Forwarded']],
      body:
        wk.per_day.length > 0
          ? wk.per_day.map((d) => [
              d.kampala_day,
              d.total_calls,
              d.made_calls,
              d.received_calls,
              d.reached_calls,
              d.engaged_calls,
              d.callback_calls,
              d.solved_here_total,
              d.forwarded_total,
            ])
          : [['—', 0, 0, 0, 0, 0, 0, 0, 0]],
      styles: { fontSize: 7, cellPadding: 1.6 },
      headStyles: { fillColor: [15, 118, 110], textColor: 255, fontStyle: 'bold' },
      didDrawPage: (d) => {
        if (d.cursor?.y) recordY(d.cursor.y);
      },
    });
    y = ((doc as any).lastAutoTable?.finalY ?? y) + 5;
    recordY(y);

    if (wk.forwarded_by_recipient.length > 0) {
      sectionHeading('2b. Weekly Forwarded Concerns by Recipient & Day (Wed–Tue)');
      const dayHeaders = wk.day_keys.length === 7 ? wk.day_keys.map((d) => d.slice(5)) : ['D1', 'D2', 'D3', 'D4', 'D5', 'D6', 'D7'];
      autoTable(doc, {
        startY: y,
        margin: { left: 12, right: 12, bottom: 16 },
        head: [['Recipient', ...dayHeaders, 'From Made', 'From Received', 'Total']],
        body: wk.forwarded_by_recipient.map((r) => [
          r.recipient_name,
          ...(r.per_day ?? [0, 0, 0, 0, 0, 0, 0]).slice(0, 7),
          r.from_made,
          r.from_received,
          r.total_forwarded,
        ]),
        styles: { fontSize: 6.8, cellPadding: 1.4 },
        headStyles: { fillColor: [51, 65, 85], textColor: 255, fontStyle: 'bold' },
        didDrawPage: (d) => {
          if (d.cursor?.y) recordY(d.cursor.y);
        },
      });
      y = ((doc as any).lastAutoTable?.finalY ?? y) + 6;
      recordY(y);
    }
  }

  // Section 3: Staff Performance
  sectionHeading('3. Staff Performance');
  autoTable(doc, {
    startY: y,
    margin: { left: 12, right: 12, bottom: 16 },
    head: [
      [
        'Staff Member',
        'Calls',
        'Reached',
        'Engaged',
        'Unreachable',
        'Callbacks',
        'Reach %',
        'Calls / Active Hr',
        'Follow-ups Owed',
        'Overdue',
      ],
    ],
    body:
      payload.staffPerformance.length > 0
        ? payload.staffPerformance.map((s) => [
            s.staff_name,
            s.total_calls,
            s.reached_calls,
            s.engaged_calls,
            s.unreachable_calls,
            s.callback_calls,
            `${s.reach_rate_pct}%`,
            s.calls_per_active_hour,
            s.followups_owed,
            s.followups_overdue,
          ])
        : [['No staff activity in range', 0, 0, 0, 0, 0, '0%', 0, 0, 0]],
    styles: { fontSize: 7, cellPadding: 1.5 },
    headStyles: { fillColor: [30, 41, 59], textColor: 255, fontStyle: 'bold' },
    didDrawPage: (d) => {
      if (d.cursor?.y) recordY(d.cursor.y);
    },
  });
  y = ((doc as any).lastAutoTable?.finalY ?? y) + 6;
  recordY(y);

  // Section 4: Registry Coverage by Region & District
  sectionHeading('4. Landlord Registry Coverage (by Region & District)');
  autoTable(doc, {
    startY: y,
    margin: { left: 12, right: 12, bottom: 16 },
    head: [
      [
        'Region',
        'District',
        'Registry Total',
        'Ever Reached',
        'Reached Round',
        'Reached Month',
        'Never Called',
        'Active Rent Plans',
      ],
    ],
    body:
      payload.coverage.length > 0
        ? payload.coverage.slice(0, 60).map((c) => [
            c.region,
            c.district,
            c.registry_total,
            c.ever_reached,
            c.reached_this_round,
            c.reached_this_month,
            c.never_called,
            c.active_rent_plans_count,
          ])
        : [['—', '—', 0, 0, 0, 0, 0, 0]],
    styles: { fontSize: 7, cellPadding: 1.5 },
    headStyles: { fillColor: [30, 41, 59], textColor: 255, fontStyle: 'bold' },
    didDrawPage: (d) => {
      if (d.cursor?.y) recordY(d.cursor.y);
    },
  });
  y = ((doc as any).lastAutoTable?.finalY ?? y) + 6;
  recordY(y);

  // Section 5: Concerns Report
  if (payload.concernsReport) {
    const cr = payload.concernsReport;
    sectionHeading('5. Landlord Concerns Report (by Category, Team & Age)');
    autoTable(doc, {
      startY: y,
      margin: { left: 12, right: 12, bottom: 16 },
      head: [['Category / Team', 'Total', 'Open', 'Completed', 'Overdue', 'Avg Age (h)']],
      body: [
        ...cr.by_category.map((c) => [
          `Category: ${c.category_label}`,
          c.total_count,
          c.open_count,
          c.completed_count,
          c.overdue_count,
          c.avg_age_hours ?? '—',
        ]),
        ...cr.by_team.map((t) => [
          `Team: ${t.team_name} (${t.recipient_name})`,
          t.total_count,
          t.open_count,
          t.completed_count,
          t.overdue_count,
          t.avg_age_hours ?? '—',
        ]),
        ...(cr.by_category.length === 0 && cr.by_team.length === 0
          ? [['No landlord concerns recorded in range', 0, 0, 0, 0, '—']]
          : []),
      ],
      styles: { fontSize: 7, cellPadding: 1.5 },
      headStyles: { fillColor: [180, 83, 9], textColor: 255, fontStyle: 'bold' },
      didDrawPage: (d) => {
        if (d.cursor?.y) recordY(d.cursor.y);
      },
    });
    y = ((doc as any).lastAutoTable?.finalY ?? y) + 6;
    recordY(y);
  }

  // Section 6: Round Report
  if (payload.roundReport?.cycle) {
    const rr = payload.roundReport;
    sectionHeading(`6. Round Report — Round #${rr.cycle?.cycle_no ?? ''} (${rr.cycle?.title ?? ''})`);
    autoTable(doc, {
      startY: y,
      margin: { left: 12, right: 12, bottom: 16 },
      head: [['Total Rows', 'Reached', 'Engaged', 'Callbacks', 'Parked', 'Outstanding', 'Total Attempts']],
      body: [
        [
          rr.totals.total_rows,
          rr.totals.reached_count,
          rr.totals.engaged_count,
          rr.totals.callback_count,
          rr.totals.parked_count,
          rr.totals.outstanding_count,
          rr.totals.total_attempts,
        ],
      ],
      styles: { fontSize: 7, cellPadding: 1.5 },
      headStyles: { fillColor: [30, 41, 59], textColor: 255, fontStyle: 'bold' },
      didDrawPage: (d) => {
        if (d.cursor?.y) recordY(d.cursor.y);
      },
    });
    y = ((doc as any).lastAutoTable?.finalY ?? y) + 6;
    recordY(y);
  }

  // Section 7: Call Log Sample
  sectionHeading(`7. Landlord Call Log (${payload.callLog.length} rows exported)`);
  autoTable(doc, {
    startY: y,
    margin: { left: 12, right: 12, bottom: 16 },
    head: [['Time', 'Landlord', 'Phone', 'Caller', 'Source', 'Outcome', 'Category', 'Note']],
    body:
      payload.callLog.length > 0
        ? payload.callLog.map((l) => [
            l.called_at ? l.called_at.slice(0, 16).replace('T', ' ') : l.kampala_day,
            l.landlord_name,
            l.phone,
            l.caller_name,
            formatCallSourceLabel(l.source),
            l.outcome.replace(/_/g, ' '),
            l.category_label,
            (l.note ?? '').slice(0, 80),
          ])
        : [['—', 'No landlord calls in selected window', '—', '—', '—', '—', '—', '—']],
    styles: { fontSize: 6.5, cellPadding: 1.4 },
    headStyles: { fillColor: [30, 41, 59], textColor: 255, fontStyle: 'bold' },
    didDrawPage: (d) => {
      if (d.cursor?.y) recordY(d.cursor.y);
    },
  });
  y = ((doc as any).lastAutoTable?.finalY ?? y) + 4;
  recordY(y);

  // Content-height page sizing capped at A4 (297 mm) + Footer with page numbers
  const totalPages = doc.getNumberOfPages();
  const pageHeights: number[] = [];

  for (let i = 1; i <= totalPages; i++) {
    doc.setPage(i);
    const maxYOnPage = pageMaxY.get(i) ?? 120;
    const cappedContentHeight = Math.min(
      A4_MAX_HEIGHT_MM,
      Math.max(MIN_CONTENT_PAGE_HEIGHT_MM, Math.ceil(maxYOnPage + 14)),
    );
    doc.internal.pageSize.height = cappedContentHeight;
    pageHeights.push(cappedContentHeight);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(100, 116, 139);
    doc.text(
      'WELILE TECHNOLOGIES LIMITED · Landlord Ops Calling Center · Confidential',
      12,
      cappedContentHeight - 5,
    );
    doc.text(`Page ${i} of ${totalPages}`, pageW - 12, cappedContentHeight - 5, {
      align: 'right',
    });
  }

  const filename = `welile-landlord-calling-report-${payload.from}-to-${payload.to}.pdf`;
  return { doc, filename, totalPages, pageHeights };
}

export async function exportLandlordCallingReportPdf(
  payload: LandlordReportExportPayload,
): Promise<BuiltLandlordReportPdf> {
  const built = buildLandlordCallingReportPdfDoc(payload);
  built.doc.save(built.filename);
  await logLandlordReportExport('pdf_report_exported', built.filename, {
    from: payload.from,
    to: payload.to,
    week_start: payload.weekStart,
    total_pages: built.totalPages,
    call_log_rows: payload.callLog.length,
  });
  return built;
}

/**
 * Pure Excel workbook sheet builder for the Landlord Calling Center reports.
 */
export function buildLandlordCallingReportXlsxSheets(
  payload: LandlordReportExportPayload,
): XlsxSheet[] {
  type ObjSheet = { name: string; rows: Record<string, string | number>[] };
  const dailySheet: ObjSheet = {
    name: 'Daily Summary',
    rows: payload.dailySummary.map((r) => ({
      'Kampala Day': r.kampala_day,
      'Staff Member': r.staff_name,
      'Total Calls': r.total_calls,
      'Reached Calls': r.reached_calls,
      'Engaged Calls': r.engaged_calls,
      'Unreachable Calls': r.unreachable_calls,
      'Callbacks Booked': r.callback_calls,
      'Outbound Made': r.made_calls,
      'Inbound Received': r.received_calls,
    })),
  };

  const weeklySheet: ObjSheet = {
    name: 'Weekly Wed-Tue',
    rows: (payload.weeklyReport?.per_day ?? []).map((d) => ({
      'Kampala Day': d.kampala_day,
      'Total Calls': d.total_calls,
      'Outbound Made': d.made_calls,
      'Inbound Received': d.received_calls,
      'Reached Calls': d.reached_calls,
      'Engaged Calls': d.engaged_calls,
      'Unreachable Calls': d.unreachable_calls,
      'Callbacks Booked': d.callback_calls,
      'Solved Here': d.solved_here_total,
      'Forwarded Concerns': d.forwarded_total,
    })),
  };

  const staffSheet: ObjSheet = {
    name: 'Staff Performance',
    rows: payload.staffPerformance.map((s) => ({
      'Staff Member': s.staff_name,
      'Total Calls': s.total_calls,
      'Reached Calls': s.reached_calls,
      'Engaged Calls': s.engaged_calls,
      'Unreachable Calls': s.unreachable_calls,
      'Callbacks Booked': s.callback_calls,
      'Unique Landlords': s.unique_landlords,
      'Reach Rate (%)': s.reach_rate_pct,
      'Active Hours': s.active_hours,
      'Calls per Active Hour': s.calls_per_active_hour,
      'Follow-ups Owed': s.followups_owed,
      'Follow-ups Overdue': s.followups_overdue,
    })),
  };

  const coverageSheet: ObjSheet = {
    name: 'Registry Coverage',
    rows: payload.coverage.map((c) => ({
      Region: c.region,
      District: c.district,
      'Registry Total': c.registry_total,
      'Ever Reached': c.ever_reached,
      'Reached This Round': c.reached_this_round,
      'Reached This Month': c.reached_this_month,
      'Never Called': c.never_called,
      'Called But Unreached': c.called_but_unreached,
      'Needs Review': c.needs_review_count,
      'Active Rent Plans': c.active_rent_plans_count,
    })),
  };

  const concernsSheet: ObjSheet = {
    name: 'Concerns Report',
    rows: (payload.concernsReport?.rows ?? []).map((c) => ({
      'Created At': c.created_at,
      Landlord: c.landlord_name,
      Category: c.category_label,
      Title: c.title,
      Priority: c.priority,
      Status: c.status,
      Team: c.team_name,
      Recipient: c.recipient_name,
      'Forwarded By': c.forwarded_by_name,
      'Age (Hours)': c.age_hours,
      Overdue: c.is_overdue ? 'Yes' : 'No',
    })),
  };

  const roundSheet: ObjSheet = {
    name: 'Round Summary',
    rows: payload.roundReport
      ? [
          {
            'Round Number': payload.roundReport.cycle?.cycle_no ?? '—',
            'Round Title': payload.roundReport.cycle?.title ?? '—',
            'Total Rows': payload.roundReport.totals.total_rows,
            Reached: payload.roundReport.totals.reached_count,
            Engaged: payload.roundReport.totals.engaged_count,
            Callbacks: payload.roundReport.totals.callback_count,
            Parked: payload.roundReport.totals.parked_count,
            Outstanding: payload.roundReport.totals.outstanding_count,
            'Total Attempts': payload.roundReport.totals.total_attempts,
          },
        ]
      : [],
  };

  const callLogSheet: ObjSheet = {
    name: 'Call Log',
    rows: payload.callLog.map((l) => ({
      'Called At': l.called_at,
      'Kampala Day': l.kampala_day,
      Landlord: l.landlord_name,
      Phone: l.phone,
      Caller: l.caller_name,
      Source: formatCallSourceLabel(l.source),
      Direction: l.direction,
      Outcome: l.outcome,
      Category: l.category_label,
      Note: l.note ?? '',
    })),
  };

  return [dailySheet, weeklySheet, staffSheet, coverageSheet, concernsSheet, roundSheet, callLogSheet]
    .map((sheet) => {
      const headers = sheet.rows.length ? Object.keys(sheet.rows[0]) : [];
      return { name: sheet.name, headers, rows: sheet.rows.map((r) => headers.map((h) => r[h])) };
    });
}

export async function exportLandlordCallingReportXlsx(
  payload: LandlordReportExportPayload,
): Promise<string> {
  const filename = `welile-landlord-calling-report-${payload.from}-to-${payload.to}.xlsx`;
  const sheets = buildLandlordCallingReportXlsxSheets(payload);
  await downloadXlsxWorkbook(filename, sheets);
  await logLandlordReportExport('bulk_data_exported', filename, {
    from: payload.from,
    to: payload.to,
    week_start: payload.weekStart,
    sheet_count: sheets.length,
    call_log_rows: payload.callLog.length,
  });
  return filename;
}

export async function exportLandlordCallLogCsv(
  rows: LandlordCallLogRow[],
  opts: { from: string; to: string; generatedBy: string },
): Promise<string> {
  const filename = `welile-landlord-call-log-${opts.from}-to-${opts.to}`;
  const headers = [
    'Called At',
    'Kampala Day',
    'Landlord',
    'Phone',
    'Caller',
    'Source',
    'Direction',
    'Outcome',
    'Category',
    'Note',
  ];
  const csvRows = rows.map((r) => [
    r.called_at,
    r.kampala_day,
    r.landlord_name,
    r.phone,
    r.caller_name,
    formatCallSourceLabel(r.source),
    r.direction,
    r.outcome,
    r.category_label,
    r.note ?? '',
  ]);

  downloadCsvWithPreamble(filename, [
    ['Report', 'Welile Landlord Ops Calling Center — Full Call Log'],
    ['Period (Kampala)', `${opts.from} to ${opts.to}`],
    ['Generated By', opts.generatedBy || 'Staff member'],
    ['Generated At', new Date().toISOString()],
    ['Total Rows', String(rows.length)],
  ], headers, csvRows);

  await logLandlordReportExport('csv_exported', `${filename}.csv`, {
    from: opts.from,
    to: opts.to,
    row_count: rows.length,
  });

  return `${filename}.csv`;
}
